package main

import (
    "bytes"
    "os/exec"
    "path/filepath"
)

func getLsResult(dirPath string) string {
    // Sanitize the directory path to prevent path traversal attacks
    sanitizedPath, err := filepath.EvalSymlinks(dirPath)
    if err != nil {
        return ""
    }

    // Ensure the path is absolute and clean
    absPath, err := filepath.Abs(sanitizedPath)
    if err != nil {
        return ""
    }

    cmd := exec.Command("ls", "-l", absPath)

    var out bytes.Buffer
    var stderr bytes.Buffer

    cmd.Stdout = &out
    cmd.Stderr = &stderr

    err = cmd.Run()
    if err != nil {
        return ""
    }

    return out.String() + stderr.String()
}

