package main

import (
    "testing"
)

func TestGetLsResult(t *testing.T) {
    // Test with existing directory
    result := getLsResult(".")
    if result == "" {
        t.Errorf("Expected non-empty output for current directory, got empty string")
    }

    // Test with non-existent directory
    result = getLsResult("/nonexistent")
    if result != "" {
        t.Errorf("Expected empty string for non-existent directory, got %s", result)
    }
}
